package com.dlt.predictor.lottery;import com.dlt.predictor.api.ApiResponse;import org.springframework.web.bind.annotation.*;import java.time.LocalDate;import java.util.*;
@RestController @RequestMapping("/api/v1/dlt/draws") public class LotteryController{private final DrawStore store;LotteryController(DrawStore s){store=s;}@GetMapping public ApiResponse<Map<String,Object>>page(@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int size,@RequestParam(required=false)String issueNo){var all=store.all().stream().filter(d->issueNo==null||d.issueNo().contains(issueNo)).toList();int from=Math.min(Math.max(0,(page-1)*Math.min(size,100)),all.size()),to=Math.min(from+Math.min(size,100),all.size());return ApiResponse.ok(Map.of("items",all.subList(from,to),"page",page,"size",size,"total",all.size()));}@GetMapping("/{issueNo}")ApiResponse<Draw>detail(@PathVariable String issueNo){return ApiResponse.ok(store.find(issueNo).orElseThrow(()->new IllegalArgumentException("期号不存在")));}}
